CREATE TABLE sys_user (id BIGINT PRIMARY KEY AUTO_INCREMENT,username VARCHAR(40) NOT NULL UNIQUE,password VARCHAR(100) NOT NULL,display_name VARCHAR(40) NOT NULL,role VARCHAR(20) NOT NULL,enabled BOOLEAN NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL);
CREATE TABLE mdm_supplier (id BIGINT PRIMARY KEY AUTO_INCREMENT,code VARCHAR(24) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,grade VARCHAR(20) NOT NULL,on_time_rate DECIMAL(5,2) NOT NULL,quality_rate DECIMAL(5,2) NOT NULL,status VARCHAR(20) NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL);
CREATE TABLE mdm_material (id BIGINT PRIMARY KEY AUTO_INCREMENT,code VARCHAR(32) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,category VARCHAR(40) NOT NULL,unit VARCHAR(16) NOT NULL,safety_stock DECIMAL(14,2) NOT NULL,current_stock DECIMAL(14,2) NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL);
CREATE TABLE mdm_demand_plan (id BIGINT PRIMARY KEY AUTO_INCREMENT,plan_no VARCHAR(32) NOT NULL UNIQUE,material_id BIGINT NOT NULL,required_qty DECIMAL(14,2) NOT NULL,required_date DATE NOT NULL,status VARCHAR(24) NOT NULL,source VARCHAR(80) NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,CONSTRAINT fk_demand_material FOREIGN KEY(material_id) REFERENCES mdm_material(id));
CREATE TABLE mdm_purchase_order (id BIGINT PRIMARY KEY AUTO_INCREMENT,order_no VARCHAR(32) NOT NULL UNIQUE,supplier_id BIGINT NOT NULL,material_id BIGINT NOT NULL,quantity DECIMAL(14,2) NOT NULL,unit_price DECIMAL(14,2) NOT NULL,expected_date DATE NOT NULL,status VARCHAR(24) NOT NULL,received_qty DECIMAL(14,2) NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,CONSTRAINT fk_po_supplier FOREIGN KEY(supplier_id) REFERENCES mdm_supplier(id),CONSTRAINT fk_po_material FOREIGN KEY(material_id) REFERENCES mdm_material(id));
CREATE TABLE mdm_supply_alert (id BIGINT PRIMARY KEY AUTO_INCREMENT,alert_type VARCHAR(30) NOT NULL,level VARCHAR(16) NOT NULL,title VARCHAR(120) NOT NULL,detail VARCHAR(300) NOT NULL,status VARCHAR(20) NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL);
CREATE INDEX idx_mdm_demand_date ON mdm_demand_plan(required_date);CREATE INDEX idx_mdm_po_status ON mdm_purchase_order(status);CREATE INDEX idx_mdm_po_expected ON mdm_purchase_order(expected_date);CREATE INDEX idx_mdm_alert_status ON mdm_supply_alert(status);
